/* ---------- 4. PAPELITOS ----------
   F(fuente, texto)            frase / enseñanza de una peli, serie o juego
   A(texto)                    dato tierno de animalitos (con onda ambiental)
   P(texto)                    "Pídeme..."
   J(emojis, opciones, correcta, extra)   adivina la peli (correcta = posición, empieza en 0)  */
// F('Película', 'texto')  -> muestra la fuente.   F('texto')  -> solo el texto, sin fuente.
const F = (fuente, texto) => texto === undefined ? { tipo: 'frase', fuente: '', texto: fuente } : { tipo: 'frase', fuente, texto };
const A = texto => ({ tipo: 'animal', texto });
const P = texto => ({ tipo: 'pide', texto });
const J = (q, opciones, correcta, extra) => ({ tipo: 'juego', q, opciones, correcta, extra });

